```ts
export class JobQueue {
  private pending: Array<() => Promise<void>> = [];
  private running = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(private concurrency: number, private maxRetries = 3) {}

  // Resolves with the job's result, or rejects once all retries have failed.
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.pending.push(() => this.attempt(job).then(resolve, reject));
      this.next();
    });
  }

  // Resolves when nothing is running and nothing is waiting.
  onIdle(): Promise<void> {
    return new Promise((resolve) => {
      this.idleWaiters.push(resolve);
      this.next();
    });
  }

  private async attempt<T>(job: () => Promise<T>): Promise<T> {
    for (let retries = 0; ; retries++) {
      try {
        return await job();
      } catch (err) {
        if (retries === this.maxRetries) throw err;
      }
    }
  }

  private next(): void {
    while (this.running < this.concurrency && this.pending.length > 0) {
      const run = this.pending.shift()!;
      this.running++;
      void run().then(() => {
        this.running--;
        this.next();
      });
    }
    if (this.running === 0 && this.pending.length === 0) {
      for (const resolve of this.idleWaiters.splice(0)) resolve();
    }
  }
}
```

A job that still fails after its three retries (four attempts in total) rejects the promise returned by `add`, so attach a `.catch` to each `add` call or Node will report an unhandled rejection. Retries happen immediately, with no delay between attempts.

```go
// Package argparse is a minimal command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flagDef struct {
	name, usage, def string
	boolVal          *bool
	strVal           *string
}

type Parser struct {
	name       string
	positional string
	flags      []*flagDef
	args       []string
}

// New creates a parser. positional describes the positional arguments in the
// help message, for example "<input> [output]".
func New(name, positional string) *Parser {
	return &Parser{name: name, positional: positional}
}

// Bool defines a boolean flag that is false unless given.
func (p *Parser) Bool(name, usage string) *bool {
	v := new(bool)
	p.flags = append(p.flags, &flagDef{name: name, usage: usage, boolVal: v})
	return v
}

// String defines a flag that takes a value.
func (p *Parser) String(name, def, usage string) *string {
	v := &def
	p.flags = append(p.flags, &flagDef{name: name, usage: usage, def: def, strVal: v})
	return v
}

// Args returns the positional arguments collected by Parse.
func (p *Parser) Args() []string { return p.args }

// Parse accepts -name, --name, --name=value and --name value. Flags and
// positional arguments may be mixed; everything after "--" is positional.
func (p *Parser) Parse(args []string) error {
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if arg == "--" {
			p.args = append(p.args, args[i+1:]...)
			return nil
		}
		if len(arg) < 2 || arg[0] != '-' {
			p.args = append(p.args, arg)
			continue
		}
		name, value, hasValue := strings.Cut(strings.TrimPrefix(arg[1:], "-"), "=")
		if name == "h" || name == "help" {
			return ErrHelp
		}
		f := p.lookup(name)
		if f == nil {
			return fmt.Errorf("unknown flag: %s", arg)
		}
		if f.boolVal != nil {
			*f.boolVal = true
			if hasValue {
				b, err := strconv.ParseBool(value)
				if err != nil {
					return fmt.Errorf("invalid boolean value %q for flag --%s", value, name)
				}
				*f.boolVal = b
			}
			continue
		}
		if !hasValue {
			if i+1 >= len(args) {
				return fmt.Errorf("flag --%s needs a value", name)
			}
			i++
			value = args[i]
		}
		*f.strVal = value
	}
	return nil
}

// Usage returns the help message generated from the flag definitions.
func (p *Parser) Usage() string {
	var b strings.Builder
	fmt.Fprintf(&b, "Usage: %s [flags] %s\n\nFlags:\n", p.name, p.positional)
	for _, f := range p.flags {
		left := "--" + f.name
		if f.strVal != nil {
			left += " <value>"
		}
		fmt.Fprintf(&b, "  %-24s %s", left, f.usage)
		if f.def != "" {
			fmt.Fprintf(&b, " (default %q)", f.def)
		}
		b.WriteByte('\n')
	}
	fmt.Fprintf(&b, "  %-24s %s\n", "-h, --help", "show this help")
	return b.String()
}

func (p *Parser) lookup(name string) *flagDef {
	for _, f := range p.flags {
		if f.name == name {
			return f
		}
	}
	return nil
}
```

