```js
const express = require("express");
const { Pool } = require("pg");

const router = express.Router();
const pool = new Pool();

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

router.get("/orders", async (req, res, next) => {
  try {
    const requested = parseInt(req.query.limit, 10) || DEFAULT_LIMIT;
    const limit = Math.min(Math.max(requested, 1), MAX_LIMIT);

    let cursor = null;
    if (req.query.cursor) {
      try {
        const [createdAt, id] = JSON.parse(
          Buffer.from(req.query.cursor, "base64url").toString()
        );
        if (typeof createdAt !== "string" || id == null) throw new Error();
        cursor = [createdAt, id];
      } catch {
        return res.status(400).json({ error: "Invalid cursor" });
      }
    }

    // Fetch one extra row to learn whether another page exists. created_at is
    // also selected as text so the cursor keeps microsecond precision, which a
    // JavaScript Date would truncate.
    const { rows } = await pool.query(
      `SELECT *, created_at::text AS cursor_created_at
         FROM orders
        ${cursor ? "WHERE (created_at, id) < ($2, $3)" : ""}
        ORDER BY created_at DESC, id DESC
        LIMIT $1`,
      cursor ? [limit + 1, ...cursor] : [limit + 1]
    );

    const page = rows.slice(0, limit);
    const last = page[page.length - 1];
    const nextCursor =
      rows.length > limit
        ? Buffer.from(
            JSON.stringify([last.cursor_created_at, last.id])
          ).toString("base64url")
        : null;

    res.json({
      data: page.map(({ cursor_created_at, ...order }) => order),
      nextCursor,
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

Create the matching index or the query will sort the whole table on every request: `CREATE INDEX ON orders (created_at DESC, id DESC);`.

